<script setup lang="ts">
import { UiButton } from '@/ui/base'
import { computed, onMounted, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { useRoute, useRouter } from 'vue-router'
import { useEnterpriseStore } from '@/stores/enterprise'
import { useUiStore } from '@/stores/ui'
import type { Member, MemberAction, MemberStatus } from '@/types/enterprise'
import { downloadCsv } from '@/utils/format'
import PageHeading from '@/ui/common/PageHeading.vue'
import AppIcon from '@/ui/common/AppIcon.vue'
import AppPagination from '@/ui/common/AppPagination.vue'
import EmptyState from '@/ui/common/EmptyState.vue'
import UiDialog from '@/ui/common/UiDialog.vue'
import MemberOverview from '@/features/enterprise/components/members/MemberOverview.vue'
import MemberFilters,{type MemberFilterValue} from '@/features/enterprise/components/members/MemberFilters.vue'
import MemberTable,{type MemberSortKey} from '@/features/enterprise/components/members/MemberTable.vue'
import MemberActionDialog from '@/features/enterprise/components/members/MemberActionDialog.vue'
import MemberDetailDrawer from '@/features/enterprise/components/members/MemberDetailDrawer.vue'
import MemberBulkDialog from '@/features/enterprise/components/members/MemberBulkDialog.vue'
import EnterpriseSourceBanner from '@/features/enterprise/components/EnterpriseSourceBanner.vue'
const store=useEnterpriseStore(),ui=useUiStore(),route=useRoute(),router=useRouter(),{t,locale}=useI18n()
const defaultFilters=():MemberFilterValue=>({query:'',role:'',department:'',status:''}); const filters=ref(defaultFilters()),page=ref(1),pageSize=ref(10),selected=ref<string[]>([]),action=ref<MemberAction>('create'),actionOpen=ref(false),target=ref<Member|null>(null),detailId=ref<string|null>(null),more=ref<Member|null>(null),sortKey=ref<MemberSortKey>(),sortDirection=ref<'asc'|'desc'>('asc'),batchOpen=ref(false),batchAction=ref<'activate'|'suspend'>('suspend'),batchTargets=ref<{id:string;version:number}[]>([])
const detail=computed(()=>store.members.find(m=>m.id===detailId.value)??null)
const filtered=computed(()=>{const {query,role,department,status}=filters.value;const result=store.members.filter(m=>(!query||`${m.name} ${m.email} ${m.phone} ${m.employeeId}`.toLowerCase().includes(query.trim().toLowerCase()))&&(!role||m.roleIds.includes(role))&&(!department||m.departmentId===department)&&(!status||m.status===status));if(!sortKey.value)return result;const key=sortKey.value;return[...result].sort((a,b)=>{const value=(m:Member)=>key==='departmentId'?store.departmentName(m.departmentId):String(m[key]??'');return value(a).localeCompare(value(b),locale.value,{numeric:true})*(sortDirection.value==='asc'?1:-1)})})
const paged=computed(()=>filtered.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value)),selection=computed(()=>store.members.filter(m=>selected.value.includes(m.id))),canActivate=computed(()=>selection.value.length>0&&selection.value.every(m=>['invited','suspended'].includes(m.status))),canSuspend=computed(()=>selection.value.length>0&&selection.value.every(m=>m.status==='active'))
watch([page,pageSize],()=>{selected.value=[]});watch(()=>filtered.value.length,()=>{page.value=Math.min(page.value,Math.max(1,Math.ceil(filtered.value.length/pageSize.value)))});watch(()=>ui.module,module=>{if(module)detailId.value=null});watch(()=>route.query,q=>{if(typeof q.q==='string'||typeof q.department==='string')applyFilters({...defaultFilters(),query:typeof q.q==='string'?q.q:'',department:typeof q.department==='string'?q.department:''});if(q.action==='create'||q.action==='invite'){openAction(q.action);void router.replace({path:route.path,query:{}})}},{immediate:true})
function scopeLabel(scope:Member['scope']){return t(`members.scopes.${scope==='department_tree'?'department':scope==='self'?'own':scope}`)}
function statusLabel(status:Member['status']){return t(`members.statuses.${status}`)}
function applyFilters(value:MemberFilterValue){filters.value={...value};page.value=1;selected.value=[];detailId.value=null}
function clear(){applyFilters(defaultFilters())}
function sort(key:MemberSortKey){sortDirection.value=sortKey.value===key&&sortDirection.value==='asc'?'desc':'asc';sortKey.value=key;page.value=1;selected.value=[]}
function openAction(kind:MemberAction,member:Member|null=null){action.value=kind;target.value=member?(JSON.parse(JSON.stringify(member)) as Member):null;more.value=null;detailId.value=null;actionOpen.value=true}
function showMore(member:Member){detailId.value=null;more.value=member}
function openBatch(kind:'activate'|'suspend'){batchAction.value=kind;batchTargets.value=selection.value.map(m=>({id:m.id,version:m.version}));batchOpen.value=true}
function finishBatch(){batchOpen.value=false;selected.value=[]}
function exportMembers(){try{const output=selected.value.length?filtered.value.filter(m=>selected.value.includes(m.id)):filtered.value;downloadCsv(t('members.exportFile'),[[t('members.columns.name'),t('members.columns.contact'),t('members.department'),t('members.role'),t('members.columns.scope'),t('members.columns.status'),t('members.columns.lastLogin'),t('members.columns.joinedAt')],...output.map(m=>[m.name,`${m.phone} / ${m.email}`,store.departmentName(m.departmentId),m.roleIds.map(store.roleName).join(', '),scopeLabel(m.scope),statusLabel(m.status),m.lastLogin||'',m.joinedAt])]);store.audit(t('members.auditModule'),t('members.auditExport'),t('members.auditCount',{count:output.length}));ui.toast(t('members.exportSuccess',{count:output.length}))}catch(e){ui.toast((e as Error).message,'error')}}
onMounted(()=>void store.ensureDomains(['members','roles','departments']).catch(()=>undefined))
</script>
<template>
  <div class="members-view" data-enterprise-page="members" data-ui-template="ListPage" :class="{'has-detail':Boolean(detail)}"><div class="member-main"><div class="page-stack members-stack"><PageHeading :title="t('members.title')" :description="t('members.description')" banner compact/><EnterpriseSourceBanner/><MemberOverview/><MemberFilters data-ui-region="query" :value="filters" @apply="applyFilters" @reset="clear"/><section data-ui-region="data" class="card member-data-panel" :aria-label="t('members.listAria')"><div class="row-between member-toolbar" data-ui-region="toolbar"><div class="row wrap member-tools"><UiButton class="btn btn-primary" @click="openAction('create')"><AppIcon name="plus" :size="16"/>{{ t('members.add') }}</UiButton><UiButton class="btn invite-button" @click="openAction('invite')"><AppIcon name="invite" :size="16"/>{{ t('members.invite') }}</UiButton><UiButton class="btn" :disabled="!canActivate" @click="openBatch('activate')"><AppIcon name="checks" :size="15"/>{{ t('members.batchActivate') }}</UiButton><UiButton class="btn" :disabled="!canSuspend" @click="openBatch('suspend')"><AppIcon name="lock" :size="14"/>{{ t('members.batchSuspend') }}</UiButton><UiButton class="btn" :aria-label="selected.length?t('members.exportSelected'):t('members.exportList')" @click="exportMembers"><AppIcon name="download" :size="15"/>{{ t('common.export') }}</UiButton></div><span class="selection-label">{{ t('common.selected',{count:selected.length}) }}<span v-if="selected.length"> · {{ t('common.currentPage') }}</span></span></div><MemberTable v-if="paged.length" v-model:selected="selected" :members="paged" :detail-id="detailId" :sort-key="sortKey" :sort-direction="sortDirection" @sort="sort" @detail="detailId=$event.id" @edit="openAction('edit',$event)" @more="showMore"/><EmptyState v-else><UiButton class="btn" @click="clear">{{ t('members.clearFilters') }}</UiButton></EmptyState><AppPagination data-ui-region="pagination" v-model:page="page" v-model:page-size="pageSize" :total="filtered.length"/></section></div></div><MemberActionDialog :open="actionOpen" :action="action" :member="target" @close="actionOpen=false"/><MemberDetailDrawer :member="detail" @close="detailId=null" @action="openAction" @more="showMore"/><MemberBulkDialog :open="batchOpen" :action="batchAction" :targets="batchTargets" @close="batchOpen=false" @saved="finishBatch"/><UiDialog :open="Boolean(more)" :title="t('members.operations',{name:more?.name??''})" width="420px" @close="more=null"><div v-if="more" class="member-operation-list"><UiButton @click="()=>{detailId=more!.id;more=null}"><AppIcon name="eye"/>{{ t('members.viewFull') }}</UiButton><UiButton @click="openAction('edit',more)"><AppIcon name="edit"/>{{ t('members.editInfo') }}</UiButton><UiButton @click="openAction('role',more)"><AppIcon name="shield"/>{{ t('members.roleChange') }}</UiButton><UiButton @click="openAction('reset',more)"><AppIcon name="key"/>{{ t('members.resetPassword') }}</UiButton><UiButton v-if="more.status==='active'" class="text-danger" @click="openAction('suspend',more)"><AppIcon name="lock"/>{{ t('members.disableAccess') }}</UiButton><UiButton v-if="(['suspended','invited'] as MemberStatus[]).includes(more.status)" @click="openAction('activate',more)"><AppIcon name="success"/>{{ t('members.reactivate') }}</UiButton><UiButton v-if="more.status!=='removed'" class="text-danger" @click="openAction('remove',more)"><AppIcon name="logout"/>{{ t('members.removeAndHandover') }}</UiButton></div></UiDialog></div>
</template>
<style scoped>
.member-main{min-width:0;container-type:inline-size;container-name:member-main}.members-view{min-width:0}.members-stack{gap:16px}.member-data-panel{padding:0 12px 12px;border-radius:var(--radius-md)}.member-toolbar{min-height:68px;padding:14px 0;flex-wrap:wrap;gap:10px}.member-tools{gap:8px}.member-tools .btn{border-color:var(--color-border)}.member-tools .btn-primary{border-color:var(--color-primary)}.member-tools .invite-button{color:var(--color-primary)}.selection-label{color:var(--color-text-muted);font-size:11px;white-space:normal;margin-left:auto}.member-data-panel :deep(.pagination){padding:20px 2px 5px;font-size:12px}.member-data-panel :deep(.pagination-controls){gap:5px}.member-operation-list{display:flex;flex-direction:column;gap:5px}.member-operation-list button{display:flex;align-items:center;gap:12px;padding:13px;border-radius:7px;text-align:left}.member-operation-list button:hover{background:var(--color-surface-soft)}.member-operation-list .icon{color:var(--color-text-secondary)}.member-operation-list .text-danger .icon{color:var(--color-danger)}@media(min-width:1280px){.members-view{transition:margin-right .24s cubic-bezier(.2,.8,.2,1)}.members-view.has-detail{margin-right:var(--member-detail-width)}}@container member-main (max-width:790px){.member-tools{gap:6px}.member-tools .btn{padding:0 10px;font-size:12px}.member-data-panel :deep(.page-jump){display:none}}@media(prefers-reduced-motion:reduce){.members-view{transition:none}}
</style>
